/* Generated for Edcor 310 Chapter 1. 150 concept-bank questions plus 5 readiness questions. */
window.PP_BANKS=window.PP_BANKS||{};window.PP_BANKS["edcor-310-ch1"]={"schema":"precise-practice/1","bank_id":"edcor-310-ch1","book":"edcor-310","chapter":1,"title":"The Purpose of Education: The Grand Adventure","storage_version":1,"status":"draft","settings":{"goals":{"1":10,"2":5,"3":3}},"concepts":[{"id":"c1","number":1,"name":"The Grand Adventure of Becoming","activities":[{"id":"C1-choice-1","type":"choice","tier":1,"title":"Core ideas","targets":["1.C1"],"status":"draft","items":[{"id":"E1-C1-1-CH1","prompt":"A system that grows stronger after a manageable challenge is best described as:","options":["fragile","resilient","antifragile","random"],"answer":2,"why":"Antifragile systems benefit from stress rather than merely surviving it.","_v":"edcor1"},{"id":"E1-C1-1-CH2","prompt":"What happens to a fragile system under stress?","options":["It becomes stronger","It returns unchanged","It breaks or loses capacity","It automatically adapts"],"answer":2,"why":"Fragile systems are harmed by shocks.","_v":"edcor1"},{"id":"E1-C1-1-CH3","prompt":"Which practice best supports antifragile learning?","options":["Remove every challenge","Give useful challenge with feedback","Avoid mistakes entirely","Reward only easy recall"],"answer":1,"why":"Appropriate challenge and feedback create opportunities to improve.","_v":"edcor1"},{"id":"E1-C1-EX1-1","prompt":"What makes an experience a desirable difficulty?","options":["It is difficult for everyone","It requires effort that supports later learning","It removes the need for feedback","It guarantees immediate fluency"],"answer":1,"why":"Desirable difficulty adds productive effort that improves later retention or transfer.","_v":"expanded-ch1"},{"id":"E1-C1-EX1-2","prompt":"A fragile competence is most likely to:","options":["Improve under every shock","Break when conditions change","Require no practice","Become antifragile automatically"],"answer":1,"why":"Fragile competence fails under stress or changed conditions.","_v":"expanded-ch1"},{"id":"E1-C1-EX1-3","prompt":"A resilient learner differs from an antifragile learner because resilience means:","options":["Returning to the prior state, while antifragility gains from challenge","Always avoiding difficulty","Never making errors","Knowing every answer in advance"],"answer":0,"why":"Resilience recovers; antifragility improves because of appropriately handled stress.","_v":"expanded-ch1"},{"id":"E1-C1-EX1-4","prompt":"Which classroom move best supports learning through challenge?","options":["Give feedback and another opportunity to use the idea","Remove every difficult task","Grade the first attempt as final","Use only familiar examples"],"answer":0,"why":"Feedback and another attempt help students adapt from challenge.","_v":"expanded-ch1"}]},{"id":"C1-choice-2","type":"choice","tier":2,"title":"Applied cases","targets":["1.C1"],"status":"draft","items":[{"id":"E1-C1-2-CH1","prompt":"A student improves after attempting a difficult problem, reviewing feedback, and trying again. This is closest to:","options":["fragility","antifragility","passive resilience","avoidance"],"answer":1,"why":"The student uses stress and feedback to build greater capability.","_v":"edcor1"},{"id":"E1-C1-2-CH2","prompt":"A course that never asks students to retrieve or apply ideas may produce:","options":["stronger transfer","fragile competence","automatic mastery","domain knowledge"],"answer":1,"why":"Competence that is never tested under challenge can fail when conditions change.","_v":"edcor1"},{"id":"E1-C1-2-CH3","prompt":"Which design is most likely to build antifragile skill?","options":["One high-stakes attempt","Repeated low-stakes attempts with feedback","No correction after errors","Only watching demonstrations"],"answer":1,"why":"Repeated attempts with feedback turn errors into information.","_v":"edcor1"},{"id":"E1-C1-EX2-1","prompt":"A student recalls a definition but cannot use it in a new case. This is best described as:","options":["Robust transfer","Context-bound competence","Antifragile expertise","Mastery of application"],"answer":1,"why":"The student’s performance has not yet survived a change in context.","_v":"expanded-ch1"},{"id":"E1-C1-EX2-2","prompt":"A task is so difficult that students cannot understand the goal or use feedback. It is most likely:","options":["Productive difficulty","Unproductive overload","Antifragile learning","Resilient transfer"],"answer":1,"why":"Challenge must be pitched so feedback can guide improvement.","_v":"expanded-ch1"},{"id":"E1-C1-EX2-3","prompt":"Why does spaced retrieval often strengthen learning?","options":["It makes every question easy","It requires reconstruction after some forgetting","It eliminates the need for knowledge","It measures personality"],"answer":1,"why":"Retrieval after time has passed strengthens access and reveals what needs more work.","_v":"expanded-ch1"},{"id":"E1-C1-EX2-4","prompt":"Which student response most clearly shows antifragility?","options":["The student avoids every difficult problem","The student uses an error to revise a strategy and improves on a new problem","The student repeats the same answer","The student performs only when prompted"],"answer":1,"why":"The learner becomes more capable through feedback from challenge.","_v":"expanded-ch1"}]},{"id":"C1-choice-3","type":"choice","tier":3,"title":"Reasoning challenge","targets":["1.C1"],"status":"draft","items":[{"id":"E1-C1-3-CH1","prompt":"A learner performs well on familiar examples but fails when the context changes. The best diagnosis is:","options":["antifragile transfer","fragile or context-bound competence","mastery of the domain","productive failure"],"answer":1,"why":"Performance that collapses under changed conditions is not robust competence.","_v":"edcor1"},{"id":"E1-C1-3-CH2","prompt":"Why can carefully chosen difficulty improve learning?","options":["Difficulty guarantees success","It creates information for adaptation","It removes the need for knowledge","It makes every task fair"],"answer":1,"why":"Challenge exposes what needs to change and supports adaptation when paired with feedback.","_v":"edcor1"},{"id":"E1-C1-3-CH3","prompt":"Which claim best captures the chapter’s view of education?","options":["Education should eliminate uncertainty","Education should help people become more capable through challenge","Education is only content delivery","Education should measure comfort"],"answer":1,"why":"The chapter treats growth through challenge as central to becoming.","_v":"edcor1"},{"id":"E1-C1-EX3-1","prompt":"A teacher says, “If students struggle, the assignment is automatically rigorous.” What is the best response?","options":["Yes, struggle always proves rigor","No; rigor requires meaningful cognitive demand and usable support","Yes, because content knowledge is irrelevant","No; rigorous work must never be difficult"],"answer":1,"why":"Difficulty alone is not rigor; the challenge must require meaningful thinking and support learning.","_v":"expanded-ch1"},{"id":"E1-C1-EX3-2","prompt":"Which course design best combines antifragility and mastery?","options":["One irreversible exam","Repeated challenging attempts with feedback and advancement after demonstrated learning","Only easy practice","A final grade based on speed"],"answer":1,"why":"Students gain capability through challenge while mastery keeps the learning target clear.","_v":"expanded-ch1"}]},{"id":"C1-quick-1","type":"quick","tier":1,"title":"Quick classify","targets":["1.C1"],"status":"draft","instructions":"Choose the label that best describes the situation.","labels":["Fragile","Antifragile"],"round_size":4,"items":[{"id":"E1-C1-1-QK1","prompt":"A glass bulb shatters when dropped.","answer":0,"why":"A fragile object is harmed by stress.","_v":"edcor1"},{"id":"E1-C1-1-QK2","prompt":"A learner uses feedback to improve after a hard attempt.","answer":1,"why":"Using challenge to improve is antifragile.","_v":"edcor1"}]},{"id":"c1-assessment-2","type":"choice","tier":2,"title":"Assessment-aligned cases","targets":["1.1.assessment"],"status":"draft","items":[{"id":"E1-C1-AS2-1","prompt":"Which learning design best reflects desirable difficulty?","options":["A single final exam with no feedback","Spaced retrieval with feedback and a gradually varied context","Removing every challenge until students feel confident","Repeating the same example without explanation"],"answer":1,"why":"Desirable difficulty makes learning effortful while feedback and variation help students adapt.","_v":"assessment-edcor1"},{"id":"E1-C1-AS2-2","prompt":"Why can a well-pitched challenge make a learner stronger?","options":["It guarantees an immediate correct answer","It reveals what can be adapted and improved","It eliminates the need for prior knowledge","It makes all tasks equally easy"],"answer":1,"why":"The chapter connects challenge, feedback, and adaptation to antifragile development.","_v":"assessment-edcor1"}]},{"id":"c1-assessment-3","type":"choice","tier":3,"title":"Assessment-aligned reasoning","targets":["1.1.assessment"],"status":"draft","items":[{"id":"E1-C1-AS3-1","prompt":"A learner succeeds on familiar examples but fails when a problem is slightly changed. What is the strongest diagnosis?","options":["The learner has robust antifragile competence","The learner has fragile or context-bound competence","The learner has mastered transfer","The learner needs no further practice"],"answer":1,"why":"Performance that collapses when conditions change is not yet robust or transferable.","_v":"assessment-edcor1"},{"id":"E1-C1-AS3-2","prompt":"Which claim best fits the chapter’s account of desirable difficulty?","options":["Difficulty is valuable only when it is random","Challenge should be pitched so students can use feedback to improve","The hardest task is always the best task","Support reduces the value of challenge"],"answer":1,"why":"The value comes from a productive challenge paired with support and feedback.","_v":"assessment-edcor1"}]}]},{"id":"c2","number":2,"name":"Bloom's Taxonomy","activities":[{"id":"C2-choice-1","type":"choice","tier":1,"title":"Core ideas","targets":["1.C2"],"status":"draft","items":[{"id":"E1-C2-1-CH1","prompt":"Which Bloom level asks students to retrieve a fact or definition?","options":["Remember","Analyze","Evaluate","Create"],"answer":0,"why":"Remembering is the retrieval level of Bloom’s cognitive taxonomy.","_v":"edcor1"},{"id":"E1-C2-1-CH2","prompt":"Which task is an example of applying?","options":["Naming the levels","Using a principle in a new case","Judging an argument","Designing a theory"],"answer":1,"why":"Applying uses known knowledge in a situation or problem.","_v":"edcor1"},{"id":"E1-C2-1-CH3","prompt":"In Bloom’s hierarchy, analyzing means:","options":["Repeating a phrase","Breaking material into parts and relationships","Choosing a personal favorite","Making a new product"],"answer":1,"why":"Analysis examines parts, structure, and relationships.","_v":"edcor1"},{"id":"E1-C2-EX1-1","prompt":"Which Bloom level is most directly involved when a student recalls a definition?","options":["Remember","Apply","Evaluate","Create"],"answer":0,"why":"Recall is the Remember level.","_v":"expanded-ch1"},{"id":"E1-C2-EX1-2","prompt":"Which Bloom level is most directly involved when a student explains an idea in their own words?","options":["Remember","Understand","Analyze","Create"],"answer":1,"why":"Explaining meaning is understanding.","_v":"expanded-ch1"},{"id":"E1-C2-EX1-3","prompt":"Which Bloom level asks students to use a principle in a new situation?","options":["Remember","Apply","Evaluate","Create"],"answer":1,"why":"Application uses knowledge in a case or problem.","_v":"expanded-ch1"},{"id":"E1-C2-EX1-4","prompt":"Which Bloom domain concerns physical coordination and procedural movement?","options":["Affective","Cognitive","Psychomotor","Normative"],"answer":2,"why":"The psychomotor domain concerns physical skill and coordination.","_v":"expanded-ch1"}]},{"id":"C2-choice-2","type":"choice","tier":2,"title":"Applied cases","targets":["1.C2"],"status":"draft","items":[{"id":"E1-C2-2-CH1","prompt":"A student compares two arguments and identifies which evidence supports each claim. That task is mainly:","options":["Remember","Understand","Analyze","Create"],"answer":2,"why":"Comparing claims and evidence requires analysis of relationships.","_v":"edcor1"},{"id":"E1-C2-2-CH2","prompt":"A student explains a concept in their own words without using it in a case. This is mainly:","options":["Understand","Apply","Evaluate","Create"],"answer":0,"why":"Explaining meaning is understanding; use in a case would be applying.","_v":"edcor1"},{"id":"E1-C2-2-CH3","prompt":"Which prompt most clearly asks students to evaluate?","options":["List three terms","Explain the diagram","Use the rule on a case","Defend which policy is best with evidence"],"answer":3,"why":"Evaluation requires a reasoned judgment supported by criteria or evidence.","_v":"edcor1"},{"id":"E1-C2-EX2-1","prompt":"A student breaks an argument into claims and evidence, then identifies how the parts relate. This is:","options":["Remembering","Analyzing","Creating","Psychomotor practice"],"answer":1,"why":"Analyzing examines parts and relationships.","_v":"expanded-ch1"},{"id":"E1-C2-EX2-2","prompt":"A student chooses the best-supported explanation using explicit criteria. This is:","options":["Understanding","Applying","Evaluating","Remembering"],"answer":2,"why":"Evaluation involves a judgment using criteria or evidence.","_v":"expanded-ch1"},{"id":"E1-C2-EX2-3","prompt":"A teacher asks students to produce a new model that explains a problem. The highest demand is:","options":["Remember","Understand","Analyze","Create"],"answer":3,"why":"Producing a new model is creation.","_v":"expanded-ch1"}]},{"id":"C2-choice-3","type":"choice","tier":3,"title":"Reasoning challenge","targets":["1.C2"],"status":"draft","items":[{"id":"E1-C2-3-CH1","prompt":"Why does a taxonomy help an instructor?","options":["It proves a student’s character","It clarifies the cognitive demand of a task","It replaces domain knowledge","It guarantees transfer"],"answer":1,"why":"A taxonomy makes the intended level of thinking more explicit.","_v":"edcor1"},{"id":"E1-C2-3-CH2","prompt":"A task asks students to design a lesson that solves a problem and justify its choices. Its highest demand is:","options":["Remember","Apply","Evaluate","Create"],"answer":3,"why":"Designing a new solution is creating, with evaluation embedded in the justification.","_v":"edcor1"},{"id":"E1-C2-3-CH3","prompt":"What is a common misuse of Bloom’s taxonomy?","options":["Using it to clarify objectives","Treating the levels as a simple measure of human worth","Writing prompts at different cognitive demands","Connecting tasks to outcomes"],"answer":1,"why":"Bloom’s framework classifies objectives; it does not rank people.","_v":"edcor1"},{"id":"E1-C2-EX3-1","prompt":"A course uses Bloom’s levels to label students as high or low thinkers. What is wrong with that use?","options":["The taxonomy classifies task demands, not a permanent worth or ability ranking","Bloom has no cognitive levels","Students should never analyze","Only affective outcomes matter"],"answer":0,"why":"Bloom’s taxonomy describes objectives and tasks; it is not a fixed ranking of people.","_v":"expanded-ch1"},{"id":"E1-C2-EX3-2","prompt":"A lesson teaches students to value intellectual honesty, practice evidence-based reasoning, and design a research study. Which statement is strongest?","options":["It addresses affective, cognitive, and possibly psychomotor dimensions rather than cognition alone","It is only Remember-level work","It cannot be rigorous because values are involved","It replaces knowledge with emotion"],"answer":0,"why":"The lesson combines values, intellectual reasoning, and practice in a broader educational purpose.","_v":"expanded-ch1"}]},{"id":"C2-compare-2","type":"compare","tier":2,"title":"Compare the levels","targets":["1.C2"],"status":"draft","instructions":"Choose the situation that best fits the concept.","labels":["A","B"],"round_size":4,"items":[{"id":"E1-C2-2-CO1","prompt":"Which task asks for the higher cognitive demand?","left":"List the stages of a process","right":"Design a new solution and justify it","answer":1,"why":"Designing and justifying a solution reaches creation.","_v":"edcor1"},{"id":"E1-C2-2-CO2","prompt":"Which prompt is more clearly evaluation?","left":"Explain what the chart shows","right":"Judge which claim is best supported by evidence","answer":1,"why":"Judging with evidence is evaluation.","_v":"edcor1"}]},{"id":"c2-assessment-1","type":"choice","tier":1,"title":"Assessment-aligned foundations","targets":["1.2.assessment"],"status":"draft","items":[{"id":"E1-C2-AS1-1","prompt":"Which activity is primarily in Bloom’s affective domain?","options":["Recalling the definition of telos","Developing a commitment to intellectual honesty","Sorting verbs by cognitive level","Designing a research method"],"answer":1,"why":"The affective domain concerns values, attitudes, and character.","_v":"assessment-edcor1"},{"id":"E1-C2-AS1-2","prompt":"Which is not one of Bloom’s cognitive levels?","options":["Understand","Analyze","ZPD","Create"],"answer":2,"why":"ZPD is a Vygotskian concept, not a level in Bloom’s cognitive taxonomy.","_v":"assessment-edcor1"}]},{"id":"c2-assessment-2","type":"choice","tier":2,"title":"Assessment-aligned applications","targets":["1.2.assessment"],"status":"draft","items":[{"id":"E1-C2-AS2-1","prompt":"A teacher asks students to compare two explanations, judge which is better supported, and defend the judgment. Which cognitive demand is most central?","options":["Remember","Analyze and evaluate","Understand only","Psychomotor practice"],"answer":1,"why":"Comparing evidence and defending a judgment require analysis and evaluation.","_v":"assessment-edcor1"},{"id":"E1-C2-AS2-2","prompt":"A student predicts how a story should change the way they treat another person. Which Bloom domain is most directly engaged?","options":["Affective","Psychomotor only","Remember","Statistical"],"answer":0,"why":"The prompt concerns values and intended disposition, which are affective outcomes.","_v":"assessment-edcor1"}]},{"id":"c2-assessment-3","type":"choice","tier":3,"title":"Assessment-aligned reasoning","targets":["1.2.assessment"],"status":"draft","items":[{"id":"E1-C2-AS3-1","prompt":"A course claims to form students who love and pursue what is good, but assesses only factual recall. What is the best critique?","options":["The assessment measures the stated affective telos directly","The assessment may measure knowledge while missing the affective purpose","Recall is always the highest Bloom level","Affective goals cannot be discussed in education"],"answer":1,"why":"A factual test can miss the values and character formation named as part of the purpose.","_v":"assessment-edcor1"}]}]},{"id":"c3","number":3,"name":"The Tragedy of Benjamin Bloom","activities":[{"id":"C3-choice-1","type":"choice","tier":1,"title":"Core ideas","targets":["1.C3"],"status":"draft","items":[{"id":"E1-C3-1-CH1","prompt":"What was central to Bloom’s mastery-learning proposal?","options":["Move on by calendar","Give students time and support until mastery","Teach only advanced students","Average every attempt"],"answer":1,"why":"Mastery learning combines clear goals, feedback, corrective work, and another chance.","_v":"edcor1"},{"id":"E1-C3-1-CH2","prompt":"The famous “two sigma” comparison concerned students taught:","options":["Only by lecture","Individually or in mastery-oriented conditions","Without feedback","Only through tests"],"answer":1,"why":"Bloom compared conventional instruction with tutoring and mastery-learning conditions.","_v":"edcor1"},{"id":"E1-C3-1-CH3","prompt":"A mastery approach treats an initial incorrect answer as:","options":["A final label","Evidence about what to learn next","Proof of low ability","A reason to lower the goal"],"answer":1,"why":"An error guides corrective instruction rather than fixing a permanent label.","_v":"edcor1"},{"id":"E1-C3-EX1-1","prompt":"In mastery learning, a first incorrect answer is best treated as:","options":["A permanent ability label","Information for corrective instruction","Proof the standard is too high","A reason to stop instruction"],"answer":1,"why":"An error identifies what the learner should work on next.","_v":"expanded-ch1"},{"id":"E1-C3-EX1-2","prompt":"What is the central sequence in mastery-oriented instruction?","options":["Teach, assess, correct, and reassess","Test once and rank","Skip feedback and advance","Lower the target after failure"],"answer":0,"why":"Mastery uses assessment and corrective work before another opportunity.","_v":"expanded-ch1"},{"id":"E1-C3-EX1-3","prompt":"Which feature is least consistent with mastery learning?","options":["Flexible time","Clear targets","Corrective feedback","Advancing only by the calendar"],"answer":3,"why":"Time-based advancement can move students forward without demonstrated mastery.","_v":"expanded-ch1"},{"id":"E1-C3-EX1-4","prompt":"The two-sigma problem is associated with comparing conventional instruction with:","options":["No instruction","Tutoring or mastery-oriented instruction","Only physical practice","A random guessing task"],"answer":1,"why":"Bloom’s comparison highlighted the gains possible under tutoring and mastery conditions.","_v":"expanded-ch1"}]},{"id":"C3-choice-2","type":"choice","tier":2,"title":"Applied cases","targets":["1.C3"],"status":"draft","items":[{"id":"E1-C3-2-CH1","prompt":"A student scores below a threshold, studies a targeted correction, retakes, and then advances. This is:","options":["mastery learning","ranking by first attempt","lowered expectations","unstructured practice"],"answer":0,"why":"The sequence uses feedback and corrective work before advancement.","_v":"edcor1"},{"id":"E1-C3-2-CH2","prompt":"A school lets students retake tests but averages all attempts without additional instruction. What is missing?","options":["A higher grade","Corrective learning before the next attempt","A calendar","A final exam"],"answer":1,"why":"Retakes become mastery-oriented when they follow feedback and corrective work.","_v":"edcor1"},{"id":"E1-C3-2-CH3","prompt":"Why can individualized tutoring outperform ordinary instruction?","options":["It removes all challenge","It provides immediate adaptation and feedback","It eliminates subject knowledge","It guarantees identical outcomes"],"answer":1,"why":"Tutoring can respond to a learner’s current understanding in real time.","_v":"edcor1"},{"id":"E1-C3-EX2-1","prompt":"A student misses a target, receives a targeted explanation, practices the gap, and retakes the assessment. The retake is most useful because it:","options":["Shows whether corrective learning produced mastery","Erases the original learning goal","Rewards speed","Replaces instruction"],"answer":0,"why":"The second opportunity tests learning after correction.","_v":"expanded-ch1"},{"id":"E1-C3-EX2-2","prompt":"What should remain constant when mastery learning varies the amount of time students receive?","options":["The learning target","The number of mistakes allowed by the calendar","The first score","The amount of homework"],"answer":0,"why":"Mastery varies support and time while keeping the target meaningful.","_v":"expanded-ch1"},{"id":"E1-C3-EX2-3","prompt":"Why can tutoring produce large gains?","options":["It can adapt explanation, feedback, and practice to the learner’s current need","It eliminates all effort","It guarantees identical personalities","It avoids assessment"],"answer":0,"why":"Responsive instruction makes correction more precise.","_v":"expanded-ch1"},{"id":"E1-C3-EX2-4","prompt":"A school allows unlimited retakes but gives no feedback or corrective work. What is missing?","options":["A mastery process","A final exam","A higher first score","A harder textbook"],"answer":0,"why":"Retakes alone do not create mastery without learning support.","_v":"expanded-ch1"}]},{"id":"C3-choice-3","type":"choice","tier":3,"title":"Reasoning challenge","targets":["1.C3"],"status":"draft","items":[{"id":"E1-C3-3-CH1","prompt":"The chapter’s tragedy is that Bloom’s work was often reduced to:","options":["A richer theory of mastery","A checklist or hierarchy detached from its instructional purpose","A tutoring program","A critique of feedback"],"answer":1,"why":"The framework’s practical vision was narrowed into a label system.","_v":"edcor1"},{"id":"E1-C3-3-CH2","prompt":"Which policy best preserves Bloom’s central insight while keeping standards high?","options":["Lower the standard for struggling students","Keep the goal, vary time and support","Use one attempt to sort students","Avoid feedback to protect confidence"],"answer":1,"why":"Mastery keeps the destination stable while adapting support and time.","_v":"edcor1"},{"id":"E1-C3-3-CH3","prompt":"What would be the strongest evidence that a mastery intervention worked?","options":["Students felt busy","Students eventually met the target after corrective instruction","The first test was difficult","Scores were averaged"],"answer":1,"why":"The key outcome is demonstrated learning after support, not initial speed.","_v":"edcor1"},{"id":"E1-C3-EX3-1","prompt":"Which criticism of a purely time-based course follows from mastery learning?","options":["Students may advance before they have learned the target","Students receive too much corrective feedback","The target is always too clear","Tutoring cannot help"],"answer":0,"why":"Calendar-based progression can separate advancement from demonstrated learning.","_v":"expanded-ch1"},{"id":"E1-C3-EX3-2","prompt":"Which policy best captures Bloom’s central instructional insight?","options":["Keep high learning targets while varying time, feedback, and corrective support","Lower targets for students who need more time","Use one score to predict potential","Remove challenging content"],"answer":0,"why":"The standard stays meaningful while instruction responds to learner needs.","_v":"expanded-ch1"}]},{"id":"C3-quick-1","type":"quick","tier":1,"title":"Quick classify","targets":["1.C3"],"status":"draft","instructions":"Choose the label that best describes the situation.","labels":["First attempt only","Mastery-oriented"],"round_size":4,"items":[{"id":"E1-C3-1-QK1","prompt":"A student is labeled permanently after one low score.","answer":0,"why":"A permanent label is not mastery learning.","_v":"edcor1"},{"id":"E1-C3-1-QK2","prompt":"A student receives correction, retakes, and advances after meeting the target.","answer":1,"why":"Corrective instruction and advancement after mastery are central to mastery learning.","_v":"edcor1"}]},{"id":"c3-assessment-2","type":"choice","tier":2,"title":"Assessment-aligned applications","targets":["1.3.assessment"],"status":"draft","items":[{"id":"E1-C3-AS2-1","prompt":"What finding is associated with Bloom’s two-sigma problem?","options":["Tutored or mastery-learning students can substantially outperform conventionally taught peers","Students learn equally well regardless of instruction","Only gifted students benefit from feedback","Mastery requires lowering the standard"],"answer":0,"why":"Bloom’s comparison highlighted the potential gains from tutoring and mastery-oriented instruction.","_v":"assessment-edcor1"},{"id":"E1-C3-AS2-2","prompt":"A mastery-learning course lets students use corrective instruction and additional time before advancing. What remains stable?","options":["Only the calendar","The learning target or standard","The first score","The amount of homework"],"answer":1,"why":"Mastery learning varies time and support while keeping the target clear.","_v":"assessment-edcor1"}]},{"id":"c3-assessment-3","type":"choice","tier":3,"title":"Assessment-aligned reasoning","targets":["1.3.assessment"],"status":"draft","items":[{"id":"E1-C3-AS3-1","prompt":"Which statement best evaluates the claim that mastery learning is incompatible with traditional grading?","options":["It is necessarily true because grades make feedback impossible","It is too strong: mastery principles can be implemented with grading if correction and revision matter","It is true because students should never be assessed","It is false because mastery means advancing by calendar"],"answer":1,"why":"The key issue is whether grading supports or defeats corrective learning and demonstrated mastery.","_v":"assessment-edcor1"},{"id":"E1-C3-AS3-2","prompt":"What is the strongest evidence that a mastery intervention worked?","options":["Students felt busy during class","Students met the target after corrective instruction and another opportunity","The first test was difficult","The teacher averaged every attempt"],"answer":1,"why":"Mastery is demonstrated by learning after feedback and support, not by initial speed.","_v":"assessment-edcor1"}]}]},{"id":"c4","number":4,"name":"High Expectations","activities":[{"id":"C4-choice-1","type":"choice","tier":1,"title":"Core ideas","targets":["1.C4"],"status":"draft","items":[{"id":"E1-C4-1-CH1","prompt":"The Pygmalion effect refers to the way:","options":["Expectations can influence performance","Tests remove bias","Students learn without instruction","Grades measure only effort"],"answer":0,"why":"Expectations can shape teacher behavior and student opportunities.","_v":"edcor1"},{"id":"E1-C4-1-CH2","prompt":"What is the misconception about lower expectations?","options":["They can limit opportunity while sounding realistic","They always provide more rigor","They increase feedback","They guarantee mastery"],"answer":0,"why":"Lower expectations may become a self-fulfilling limit.","_v":"edcor1"},{"id":"E1-C4-1-CH3","prompt":"High expectations should be paired with:","options":["No support","Clear support and feedback","Less practice","Lower standards"],"answer":1,"why":"High expectations are ethical when students receive the support needed to meet them.","_v":"edcor1"},{"id":"E1-C4-EX1-1","prompt":"The Pygmalion effect concerns the influence of:","options":["Teacher expectations on student opportunities and performance","School calendars on attendance","Test length on memory","Physical practice on coordination"],"answer":0,"why":"Expectations can influence behavior and opportunities that affect performance.","_v":"expanded-ch1"},{"id":"E1-C4-EX1-2","prompt":"Which response reflects high expectations?","options":["Keep the goal and provide support","Lower the goal immediately","Avoid challenging work","Praise without teaching"],"answer":0,"why":"High expectations pair a demanding goal with support.","_v":"expanded-ch1"},{"id":"E1-C4-EX1-3","prompt":"What is a risk of assuming a struggling student cannot handle complex work?","options":["The student may receive fewer opportunities and perform below potential","The student automatically becomes antifragile","The standard becomes clearer","Feedback becomes more precise"],"answer":0,"why":"Expectations can shape the opportunities students receive.","_v":"expanded-ch1"},{"id":"E1-C4-EX1-4","prompt":"Which teacher behavior can communicate a low expectation?","options":["Providing less wait time and simpler work to one student","Offering models and feedback","Inviting a student to justify a claim","Allowing revision after feedback"],"answer":0,"why":"Unequal opportunity and reduced challenge can communicate low expectations.","_v":"expanded-ch1"}]},{"id":"C4-choice-2","type":"choice","tier":2,"title":"Applied cases","targets":["1.C4"],"status":"draft","items":[{"id":"E1-C4-2-CH1","prompt":"A teacher assumes a student cannot handle complex work and gives only simple worksheets. This illustrates:","options":["a self-fulfilling expectation","mastery learning","domain transfer","productive failure"],"answer":0,"why":"The expectation changes the opportunities offered, which can affect performance.","_v":"edcor1"},{"id":"E1-C4-2-CH2","prompt":"Which response best reflects high expectations?","options":["Keep the goal and add scaffolding","Remove the difficult goal","Give praise without instruction","Wait for students to teach themselves"],"answer":0,"why":"Scaffolding supports students without abandoning the demanding target.","_v":"edcor1"},{"id":"E1-C4-2-CH3","prompt":"If a student is struggling, the chapter recommends first asking:","options":["How can the task be made easier forever?","What support and instruction would help the student reach the goal?","Should the student be excluded?","Can the standard be removed?"],"answer":1,"why":"The focus is on support and instruction rather than a fixed judgment.","_v":"edcor1"},{"id":"E1-C4-EX2-1","prompt":"A teacher believes a student can reason well and gives the student time to explain, feedback, and challenging examples. This illustrates:","options":["An expectation operating through instructional behavior","A Type II error","Psychomotor learning","Calendar progression"],"answer":0,"why":"Expectations can influence concrete interactions and opportunities.","_v":"expanded-ch1"},{"id":"E1-C4-EX2-2","prompt":"Why are high expectations not the same as simply being optimistic?","options":["They require instruction and support that help students reach the goal","They eliminate the need for standards","They guarantee equal scores","They avoid difficult feedback"],"answer":0,"why":"Belief without effective teaching does not make a demanding target reachable.","_v":"expanded-ch1"},{"id":"E1-C4-EX2-3","prompt":"Which response best balances accommodation and expectations?","options":["Provide needed support while preserving meaningful learning goals","Remove the learning goal entirely","Give only easier work forever","Treat accommodation as proof of inability"],"answer":0,"why":"Support should improve access without abandoning the target.","_v":"expanded-ch1"},{"id":"E1-C4-EX2-4","prompt":"If students are given challenging work but no modeling, feedback, or time, the main problem is:","options":["The pathway to the expectation is missing","The standard is necessarily too low","The class is automatically rigorous","The Pygmalion effect cannot exist"],"answer":0,"why":"Students need usable instructional support to meet high expectations.","_v":"expanded-ch1"}]},{"id":"C4-choice-3","type":"choice","tier":3,"title":"Reasoning challenge","targets":["1.C4"],"status":"draft","items":[{"id":"E1-C4-3-CH1","prompt":"Why are high expectations a moral commitment rather than just a motivational trick?","options":["They determine who receives meaningful opportunities to learn","They make all students identical","They remove the need for teaching","They guarantee equal scores"],"answer":0,"why":"Expectations influence the seriousness and quality of opportunities students receive.","_v":"edcor1"},{"id":"E1-C4-3-CH2","prompt":"A teacher believes in students but provides no models, feedback, or time. What is incomplete?","options":["Belief alone is enough","High expectations require instructional support","Rigor is impossible","Standards should be lowered"],"answer":1,"why":"Hope without useful teaching does not create access to the target.","_v":"edcor1"},{"id":"E1-C4-3-CH3","prompt":"Which pattern best distinguishes rigor from unreasonable demand?","options":["Demand without support","A challenging goal with instruction, feedback, and revision","Easy tasks with high praise","A single timed test"],"answer":1,"why":"Rigor pairs meaningful challenge with a path to improvement.","_v":"edcor1"},{"id":"E1-C4-EX3-1","prompt":"Which conclusion about Pygmalion effects is most defensible?","options":["Expectations can matter through behavior, but they do not explain every outcome or replace good instruction","Believing harder guarantees every result","Teacher expectations never affect opportunity","All differences are caused by expectations"],"answer":0,"why":"The effect is a mechanism of influence, not a complete explanation of achievement.","_v":"expanded-ch1"},{"id":"E1-C4-EX3-2","prompt":"A teacher wants to avoid both low expectations and empty praise. Which practice is best?","options":["Set a demanding target, provide evidence-based support, and give specific feedback","Praise every answer regardless of quality","Remove difficult tasks","Use the same support regardless of need"],"answer":0,"why":"Calibrated support preserves standards while giving students information for improvement.","_v":"expanded-ch1"}]},{"id":"C4-compare-2","type":"compare","tier":2,"title":"Compare the responses","targets":["1.C4"],"status":"draft","instructions":"Choose the situation that best fits the concept.","labels":["A","B"],"round_size":4,"items":[{"id":"E1-C4-2-CO1","prompt":"Which response better preserves high expectations?","left":"Lower the goal when work is difficult","right":"Keep the goal and add scaffolding","answer":1,"why":"Scaffolding supports the same demanding goal.","_v":"edcor1"},{"id":"E1-C4-2-CO2","prompt":"Which teacher behavior could create a self-fulfilling expectation?","left":"Offering complex work with support","right":"Offering only simple work because a student is presumed incapable","answer":1,"why":"Reduced opportunity can help produce the expected lower performance.","_v":"edcor1"}]},{"id":"c4-assessment-2","type":"choice","tier":2,"title":"Assessment-aligned applications","targets":["1.4.assessment"],"status":"draft","items":[{"id":"E1-C4-AS2-1","prompt":"Through which teacher behavior can expectations plausibly influence student performance?","options":["Giving more useful feedback and opportunities to explain","Keeping expectations private and never changing instruction","Removing challenging work from selected students","Scoring without observing student work"],"answer":0,"why":"Expectations can operate through differences in feedback, wait time, attention, and opportunity.","_v":"assessment-edcor1"},{"id":"E1-C4-AS2-2","prompt":"A teacher genuinely believes in students but provides no models, feedback, or time. What is missing?","options":["A lower standard","Instructional support that makes the expectation reachable","A permanent label","Less cognitive demand"],"answer":1,"why":"Belief alone does not provide students a path toward a demanding goal.","_v":"assessment-edcor1"}]},{"id":"c4-assessment-3","type":"choice","tier":3,"title":"Assessment-aligned reasoning","targets":["1.4.assessment"],"status":"draft","items":[{"id":"E1-C4-AS3-1","prompt":"Which statement about the Pygmalion effect is most accurate?","options":["It can be produced simply by believing in students","Teacher expectations can shape behavior and opportunity, so expectations require careful calibration and support","It proves every difference in achievement is caused by teachers","It means accommodations are always inappropriate"],"answer":1,"why":"The effect concerns causal expectation channels; responsible practice pairs high expectations with support and calibration.","_v":"assessment-edcor1"},{"id":"E1-C4-AS3-2","prompt":"A teacher lowers output expectations for a student while offering accommodation. What is the best response?","options":["Accommodation and lowered learning expectations are identical","Support can be appropriate, but abandoning the learning target may create a Pygmalion concern","All expectations should be removed","The student should receive only praise"],"answer":1,"why":"The issue is whether support preserves meaningful learning expectations rather than abandoning them.","_v":"assessment-edcor1"}]}]},{"id":"c5","number":5,"name":"Domain-Specific Knowledge","activities":[{"id":"C5-choice-1","type":"choice","tier":1,"title":"Core ideas","targets":["1.C5"],"status":"draft","items":[{"id":"E1-C5-1-CH1","prompt":"Willingham’s central claim is that critical thinking:","options":["Is a general skill independent of content","Depends heavily on domain knowledge","Requires no practice","Replaces factual knowledge"],"answer":1,"why":"Thinking skills are tied to the knowledge available in a domain.","_v":"edcor1"},{"id":"E1-C5-1-CH2","prompt":"Why does background knowledge help comprehension?","options":["It supplies a structure for interpreting new information","It prevents questions","It removes the need to read","It guarantees agreement"],"answer":0,"why":"Existing knowledge helps readers connect and interpret new information.","_v":"edcor1"},{"id":"E1-C5-1-CH3","prompt":"Which is a domain-specific skill?","options":["Analyzing evidence in a historical source","Being smart in every context","Trying harder","Having a high score"],"answer":0,"why":"Analysis depends on the concepts, evidence, and conventions of the domain.","_v":"edcor1"},{"id":"E1-C5-EX1-1","prompt":"What does domain-specific knowledge provide for reasoning?","options":["Concepts and evidence that make interpretation possible","A guarantee of agreement","A replacement for practice","A way to avoid reading"],"answer":0,"why":"Knowledge supplies the material and structure for reasoning.","_v":"expanded-ch1"},{"id":"E1-C5-EX1-2","prompt":"Which student is most likely to analyze a new historical source well?","options":["A student with relevant historical background knowledge","A student who knows only a generic thinking slogan","A student who has never encountered the topic","A student who avoids evidence"],"answer":0,"why":"Relevant knowledge supports interpretation and evaluation.","_v":"expanded-ch1"},{"id":"E1-C5-EX1-3","prompt":"Critical thinking is not fully transferable because:","options":["Reasoning depends partly on what a person knows in the domain","Thinking never involves knowledge","All subjects use identical evidence","Practice is unnecessary"],"answer":0,"why":"The knowledge base shapes what reasoning is possible.","_v":"expanded-ch1"},{"id":"E1-C5-EX1-4","prompt":"Which is a better foundation for learning to evaluate evidence?","options":["Teach the domain’s concepts and examples before asking for evaluation","Teach only the word critical","Skip background information","Use only a speed test"],"answer":0,"why":"Students need relevant content knowledge to make informed evaluations.","_v":"expanded-ch1"}]},{"id":"C5-choice-2","type":"choice","tier":2,"title":"Applied cases","targets":["1.C5"],"status":"draft","items":[{"id":"E1-C5-2-CH1","prompt":"A student can identify bias in a familiar history topic but not in an unfamiliar scientific article. This suggests:","options":["thinking transfers automatically","critical thinking is partly domain-specific","knowledge blocks reasoning","the student learned nothing"],"answer":1,"why":"Reasoning performance can change when the relevant knowledge base changes.","_v":"edcor1"},{"id":"E1-C5-2-CH2","prompt":"Which lesson best supports transfer?","options":["Teach a generic thinking slogan","Build knowledge, then practice reasoning across related cases","Skip content and teach only debate","Use one example once"],"answer":1,"why":"Transfer improves when students have knowledge and practice applying it in varied cases.","_v":"edcor1"},{"id":"E1-C5-2-CH3","prompt":"Why might a class discussion fail to produce deep analysis?","options":["Students have too much knowledge","Students lack the background needed to evaluate the evidence","Discussion always lowers rigor","Facts make thinking impossible"],"answer":1,"why":"Without relevant knowledge, analysis can become shallow or unsupported.","_v":"edcor1"},{"id":"E1-C5-EX2-1","prompt":"A student can identify bias in a familiar history unit but not an unfamiliar science article. The best explanation is:","options":["The relevant knowledge base differs across domains","The student has no critical-thinking ability","History requires no evidence","Science cannot be analyzed"],"answer":0,"why":"Reasoning can depend on knowledge specific to the domain.","_v":"expanded-ch1"},{"id":"E1-C5-EX2-2","prompt":"Which sequence is most likely to support transfer?","options":["Build domain knowledge, model reasoning, then practice across related cases","Teach a generic slogan once","Start with an unfamiliar case and provide no background","Assess recall only"],"answer":0,"why":"Knowledge and guided variation create a foundation for transfer.","_v":"expanded-ch1"},{"id":"E1-C5-EX2-3","prompt":"Why can a discussion remain shallow even when students are asked to think critically?","options":["Students may lack the background knowledge needed to evaluate the claims","Discussion always prevents reasoning","Facts make thinking impossible","The teacher used too many examples"],"answer":0,"why":"Without relevant knowledge, students may have no evidence base for analysis.","_v":"expanded-ch1"},{"id":"E1-C5-EX2-4","prompt":"Which assessment best tests whether students can reason with domain knowledge?","options":["A new case requiring evidence and a justified conclusion","Copying definitions","Choosing the longest answer","Recalling a single date"],"answer":0,"why":"A new case tests use of knowledge in reasoning.","_v":"expanded-ch1"}]},{"id":"C5-choice-3","type":"choice","tier":3,"title":"Reasoning challenge","targets":["1.C5"],"status":"draft","items":[{"id":"E1-C5-3-CH1","prompt":"The chapter’s prescription for critical thinking is best summarized as:","options":["Teach more domain knowledge and then use it for reasoning","Choose skills instead of content","Avoid factual recall","Assume transfer"],"answer":0,"why":"Domain knowledge is a foundation on which higher-order reasoning can operate.","_v":"edcor1"},{"id":"E1-C5-3-CH2","prompt":"A student memorizes vocabulary but cannot explain a new example. What is most needed?","options":["More isolated words","Guided application in the domain","Less practice","A lower standard"],"answer":1,"why":"Application connects knowledge to new cases and reveals what the learner understands.","_v":"edcor1"},{"id":"E1-C5-3-CH3","prompt":"Which assessment best tests knowledge-based reasoning?","options":["A list of terms only","A new case requiring evidence from the domain","A popularity vote","A speed contest"],"answer":1,"why":"A new case tests whether students can use domain knowledge to reason.","_v":"edcor1"},{"id":"E1-C5-EX3-1","prompt":"A team teaches generic critical-thinking routines but little subject matter. What is the strongest concern?","options":["The routines may not transfer because reasoning is tied to domain knowledge","Students will automatically become experts","Facts are unnecessary for analysis","Transfer is guaranteed by repetition"],"answer":0,"why":"Willingham’s argument predicts limited transfer without a rich knowledge base.","_v":"expanded-ch1"},{"id":"E1-C5-EX3-2","prompt":"Which claim best reflects the chapter’s view of expertise?","options":["Expert reasoning is supported by organized knowledge, not just a general thinking habit","Expertise is only confidence","Experts never use facts","All reasoning is context-free"],"answer":0,"why":"Domain knowledge makes complex reasoning faster and more accurate.","_v":"expanded-ch1"}]},{"id":"C5-quick-1","type":"quick","tier":1,"title":"Quick classify","targets":["1.C5"],"status":"draft","instructions":"Choose the label that best describes the situation.","labels":["Knowledge foundation","Generic shortcut"],"round_size":4,"items":[{"id":"E1-C5-1-QK1","prompt":"Teach the concepts and evidence needed to analyze a source.","answer":0,"why":"Domain knowledge supports meaningful analysis.","_v":"edcor1"},{"id":"E1-C5-1-QK2","prompt":"Teach a slogan about critical thinking without the subject matter.","answer":1,"why":"A generic slogan cannot replace domain knowledge.","_v":"edcor1"}]},{"id":"c5-assessment-2","type":"choice","tier":2,"title":"Assessment-aligned applications","targets":["1.5.assessment"],"status":"draft","items":[{"id":"E1-C5-AS2-1","prompt":"A student identifies bias in a familiar history source but not in an unfamiliar science article. What does this best illustrate?","options":["Critical thinking transfers automatically","Reasoning depends partly on domain-specific knowledge","Facts prevent analysis","The student has no reasoning ability"],"answer":1,"why":"The relevant knowledge base helps make reasoning possible in each domain.","_v":"assessment-edcor1"},{"id":"E1-C5-AS2-2","prompt":"What should a teacher do before asking students to evaluate a complex source?","options":["Teach the relevant concepts and evidence base","Replace content with generic thinking slogans","Avoid modeling the reasoning","Assume transfer from any topic"],"answer":0,"why":"Background knowledge gives students the material needed for meaningful evaluation.","_v":"assessment-edcor1"}]},{"id":"c5-assessment-3","type":"choice","tier":3,"title":"Assessment-aligned reasoning","targets":["1.5.assessment"],"status":"draft","items":[{"id":"E1-C5-AS3-1","prompt":"A team spends most of its time teaching generic critical-thinking routines but gives students little history, science, or literature knowledge. What is the best prediction?","options":["The routines will transfer automatically to every domain","The team may underdeliver because reasoning depends on rich domain knowledge","Students will no longer need practice","More generic routines guarantee expertise"],"answer":1,"why":"Willingham’s claim is that critical thinking is not independent of the knowledge base.","_v":"assessment-edcor1"},{"id":"E1-C5-AS3-2","prompt":"Which assessment most directly tests knowledge-based reasoning?","options":["A list of isolated terms","A new domain case requiring evidence and a justified conclusion","A popularity vote","A timed copying exercise"],"answer":1,"why":"A new case tests whether students can use domain knowledge to reason.","_v":"assessment-edcor1"}]}]},{"id":"c6","number":6,"name":"Teleology and Rigor","activities":[{"id":"C6-choice-1","type":"choice","tier":1,"title":"Core ideas","targets":["1.C6"],"status":"draft","items":[{"id":"E1-C6-1-CH1","prompt":"Teleology asks about a thing’s:","options":["price","purpose or end","speed","difficulty"],"answer":1,"why":"Telos means the end, purpose, or what something is for.","_v":"edcor1"},{"id":"E1-C6-1-CH2","prompt":"Rigor is best understood as:","options":["Making work difficult for its own sake","Requiring meaningful thinking supported by knowledge and evidence","Giving more homework","Using a timer"],"answer":1,"why":"Rigor concerns the quality and cognitive demand of thinking, not mere difficulty.","_v":"edcor1"},{"id":"E1-C6-1-CH3","prompt":"A class in which every student earns an A can still be rigorous if:","options":["The tasks require substantial reasoning and students meet the standard","Grades are given randomly","No one receives feedback","The work is always easy"],"answer":0,"why":"High performance does not by itself indicate low rigor.","_v":"edcor1"},{"id":"E1-C6-EX1-1","prompt":"Telos means:","options":["The purpose or end a thing is for","The amount of work assigned","The speed of progress","The score on a test"],"answer":0,"why":"Telos names purpose or end.","_v":"expanded-ch1"},{"id":"E1-C6-EX1-2","prompt":"Rigor is not the same as:","options":["Meaningful cognitive demand","Volume or busywork","Reasoned judgment","Transfer to a new case"],"answer":1,"why":"Large workloads can be low in cognitive demand.","_v":"expanded-ch1"},{"id":"E1-C6-EX1-3","prompt":"Which task has the greatest need for judgment?","options":["Choosing and defending which principle applies to a new case","Copying a definition","Repeating a worked example","Listing vocabulary"],"answer":0,"why":"Judgment requires deciding among defensible alternatives.","_v":"expanded-ch1"},{"id":"E1-C6-EX1-4","prompt":"A course’s telos asks what students are becoming, not merely what they can:","options":["Repeat on a worksheet","Memorize for one test","Both A and B","Practice with feedback"],"answer":2,"why":"A purpose-centered education looks beyond short-term performance and repetition.","_v":"expanded-ch1"}]},{"id":"C6-choice-2","type":"choice","tier":2,"title":"Applied cases","targets":["1.C6"],"status":"draft","items":[{"id":"E1-C6-2-CH1","prompt":"A teacher raises the reading level but removes the need to reason. The change is:","options":["necessarily more rigorous","harder but not necessarily more rigorous","mastery learning","teleological"],"answer":1,"why":"Difficulty without meaningful cognitive demand is not rigor.","_v":"edcor1"},{"id":"E1-C6-2-CH2","prompt":"If the telos of education is human flourishing, an assessment should primarily ask whether students:","options":["can sort themselves by speed","are becoming more capable of understanding and acting well","avoid all mistakes","memorize without purpose"],"answer":1,"why":"Purpose should guide what the assessment values.","_v":"edcor1"},{"id":"E1-C6-2-CH3","prompt":"Which task most clearly combines rigor with purpose?","options":["Defend a claim with domain evidence and explain its consequences","Copy a definition ten times","Complete a longer worksheet","Guess the teacher’s preference"],"answer":0,"why":"The task requires evidence, reasoning, and attention to consequences.","_v":"edcor1"},{"id":"E1-C6-EX2-1","prompt":"Which assignment is more rigorous?","options":["A longer worksheet repeating a demonstrated method","A shorter set of unfamiliar cases requiring justified choices","A larger vocabulary list","A faster recall quiz"],"answer":1,"why":"Rigor concerns cognitive demand, especially transfer and justification.","_v":"expanded-ch1"},{"id":"E1-C6-EX2-2","prompt":"Why does telos matter for assessment?","options":["Purpose determines which forms of growth count as success","Purpose makes evidence unnecessary","Purpose requires every student to learn identically","Purpose is unrelated to tasks"],"answer":0,"why":"Assessments should reflect what education is for.","_v":"expanded-ch1"},{"id":"E1-C6-EX2-3","prompt":"A school claims to develop independent thinkers but rewards only rapid recall. This is primarily:","options":["A mismatch between stated purpose and practice","Evidence of mastery learning","Proof of high rigor","A psychomotor goal"],"answer":0,"why":"The incentives do not match the stated telos.","_v":"expanded-ch1"},{"id":"E1-C6-EX2-4","prompt":"A challenging task with clear evidence, feedback, and revision is more rigorous than a long task because it:","options":["Requires meaningful thinking rather than merely more work","Always takes less time","Uses fewer words","Avoids content knowledge"],"answer":0,"why":"Cognitive demand and reasoning matter more than volume.","_v":"expanded-ch1"}]},{"id":"C6-choice-3","type":"choice","tier":3,"title":"Reasoning challenge","targets":["1.C6"],"status":"draft","items":[{"id":"E1-C6-3-CH1","prompt":"Why does the question “What is education for?” matter for assessment design?","options":["It determines which abilities and forms of growth count as success","It makes measurement impossible","It replaces content knowledge","It guarantees one correct philosophy"],"answer":0,"why":"A theory of purpose shapes the outcomes an educational system chooses to cultivate.","_v":"edcor1"},{"id":"E1-C6-3-CH2","prompt":"A school rewards only short-term recall although it claims to develop independent thinkers. The problem is mainly:","options":["a mismatch between telos and practice","too much rigor","mastery learning","domain specificity"],"answer":0,"why":"The stated end and the actual incentives point in different directions.","_v":"edcor1"},{"id":"E1-C6-3-CH3","prompt":"Which conclusion best follows from the chapter?","options":["Rigor is meaningful only when connected to what students are meant to become","Rigor means maximum workload","Purpose is irrelevant to teaching","All students must learn identically"],"answer":0,"why":"Challenge should serve an educational purpose rather than become an end in itself.","_v":"edcor1"},{"id":"E1-C6-EX3-1","prompt":"A teacher calls a 12-page assignment more rigorous than a four-question transfer task solely because it is longer. What is the best critique?","options":["Length measures volume, not necessarily cognitive demand","Length always proves rigor","Transfer tasks cannot be rigorous","Rigor is impossible to compare"],"answer":0,"why":"The course defines rigor by the thinking demanded, not the amount of work.","_v":"expanded-ch1"},{"id":"E1-C6-EX3-2","prompt":"Which student best demonstrates the course’s telos?","options":["A student whose judgment and response have been formed, not only a student who can recite terms","A student who memorizes without applying","A student who finishes fastest","A student who avoids difficult questions"],"answer":0,"why":"Person-formation and changed judgment are part of the educational purpose.","_v":"expanded-ch1"}]},{"id":"C6-compare-2","type":"compare","tier":2,"title":"Compare the tasks","targets":["1.C6"],"status":"draft","instructions":"Choose the situation that best fits the concept.","labels":["A","B"],"round_size":4,"items":[{"id":"E1-C6-2-CO1","prompt":"Which task is more rigorous?","left":"Copy a definition ten times","right":"Defend a claim with evidence and explain consequences","answer":1,"why":"The second task requires reasoning with evidence.","_v":"edcor1"},{"id":"E1-C6-2-CO2","prompt":"Which school practice best matches its stated purpose of developing independent thinkers?","left":"Reward only short-term recall","right":"Assess students’ ability to use knowledge in new cases","answer":1,"why":"Using knowledge in new cases better matches independent thinking.","_v":"edcor1"}]},{"id":"c6-assessment-2","type":"choice","tier":2,"title":"Assessment-aligned applications","targets":["1.6.assessment"],"status":"draft","items":[{"id":"E1-C6-AS2-1","prompt":"Which statement best defines telos?","options":["The volume of work assigned","The purpose or end a thing is for","The speed of learning","The number of points on a test"],"answer":1,"why":"Telos names the purpose or end toward which something is directed.","_v":"assessment-edcor1"},{"id":"E1-C6-AS2-2","prompt":"Which assignment is more rigorous under the chapter’s definition?","options":["Forty terms copied from a glossary","Four unfamiliar cases requiring students to choose and defend a principle","A longer worksheet using one demonstrated example","A faster timed recall test"],"answer":1,"why":"Rigor is cognitive demand, especially transfer and judgment, not workload or pace.","_v":"assessment-edcor1"}]},{"id":"c6-assessment-3","type":"choice","tier":3,"title":"Assessment-aligned reasoning","targets":["1.6.assessment"],"status":"draft","items":[{"id":"E1-C6-AS3-1","prompt":"Version 1 has 40 terms, a 12-page reading, and repeated worked examples. Version 2 has 6 terms, a 3-page reading, and unfamiliar cases requiring justified decisions. Which is more rigorous?","options":["Version 1, because volume is rigor","Version 2, because it requires transfer and judgment","They are equal because rigor is subjective","Neither, because rigor requires obscure content"],"answer":1,"why":"Version 2 places greater cognitive demand on transfer and judgment rather than volume.","_v":"assessment-edcor1"},{"id":"E1-C6-AS3-2","prompt":"Two students finish a course. Dana recalls every term but treats teaching as merely delivering information. Avery recalls less but has changed how she notices and responds to students. By the course’s telos, which judgment is strongest?","options":["Dana, because recall is the only evidence of learning","Avery, because formation includes changed judgment and response","Both equally, because completion proves the telos","Neither, because telos applies only to institutions"],"answer":1,"why":"The chapter’s telos is person-formation, not only accurate verbal recall.","_v":"assessment-edcor1"}]}]}],"readiness":{"streak":5,"items":[{"id":"E1-R01","prompt":"Which claim best captures why education should include both knowledge and higher-order reasoning?","options":["Reasoning is independent of content.","Domain knowledge gives reasoning something to work with.","Facts make analysis impossible.","Only recall can be assessed."],"answer":1,"why":"The chapter argues that meaningful reasoning depends on knowledge in a domain."},{"id":"E1-R02","prompt":"A teacher keeps a demanding goal but adds feedback and corrective practice. Which principle is this?","options":["Lowered expectations","Mastery learning","Rigor as workload","Avoidance of challenge"],"answer":1,"why":"Mastery learning keeps the target while varying time and support."},{"id":"E1-R03","prompt":"Which statement best distinguishes rigor from mere difficulty?","options":["Rigor is more homework.","Rigor is meaningful thinking connected to a purpose.","Rigor is a faster timer.","Rigor is a harder textbook."],"answer":1,"why":"Rigor concerns cognitive demand and purpose, not difficulty alone."},{"id":"E1-R04","prompt":"A learner improves after a challenge because feedback reveals what to change. This illustrates:","options":["Fragility","Antifragile development","A fixed ability","Lower expectations"],"answer":1,"why":"Antifragile development uses challenge and feedback to become stronger."},{"id":"E1-R05","prompt":"Why should high expectations be paired with instructional support?","options":["Support makes the goal less demanding.","Support gives students a path to reach the demanding goal.","Support replaces knowledge.","Support guarantees identical outcomes."],"answer":1,"why":"High expectations are meaningful when students receive instruction, feedback, and time."}]}};